{
  "copy": "<div id="manualInvoiceSection" class="row sectionBlockLayout text-left" style="display: flex; flex-wrap: wrap; margin: 0px; text-align: left; min-height: auto; padding: 8px;">
  <div class="container" style="display: flex; flex-wrap: wrap;"><div class="col-md-12 columnBlockLayout" style="flex-grow: 1; display: flex; flex-direction: column; min-width: 250px; padding: 16px; margin: 60px 0px;">{% entityform name: 'Client Expense Edit - QP' %}</div></div>
</div>

<!-- Page Not Found Message -->
<section id="pageNotFound" class="not-found" style="display: none;">
  <div class="container" style="padding: 0px; display: flex; flex-wrap: wrap;">
    <div class="col-md-12 columnBlockLayout" style="flex-grow: 1; display: flex; flex-direction: column; min-width: 300px; padding: 16px;"><img src="/Cat-PC.png" alt="" name="Cat-PC.png" style="width: 200px; height: 161px; margin-left: auto; margin-right: auto;">
      <h2 style="text-align: center; color: var(--portalThemeColor4);">Page not found</h2>
      <p style="text-align: center; color: var(--portalThemeColor8);">Check the link and try again</p>
    </div>
  </div>
</section>
